import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.2af478d7.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function i(s,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><code>proteo/drupal-backend</code> turns a Drupal site into the content backend of a Laravel app. You describe your Drupal content once, in a PHP file called the <a href="./vocabulary#descriptor">descriptor</a>, and the package fetches, caches, maps and routes it for you.</p><h2 id="who-it-is-for" tabindex="-1">Who it is for <a class="header-anchor" href="#who-it-is-for" aria-label="Permalink to &quot;Who it is for&quot;">​</a></h2><p>You are a Laravel developer building a frontend for content that editors manage in Drupal. You want typed objects in your Blade views, not raw JSON:API documents, and you do not want to write a fetcher, a cache and a webhook for every content type.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li><strong>Content pages without controllers.</strong> Each <a href="./vocabulary#content-type">content type</a> in the descriptor gets a listing route, an item route and a default view. You override the views, not the plumbing.</li><li><strong>A read model.</strong> Views receive an <a href="./vocabulary#entity">Entity</a> whose properties carry the names you chose, not Drupal&#39;s field names.</li><li><strong>A cache that stays current.</strong> Responses are cached with a stale-while-revalidate window, and a signed <a href="./vocabulary#webhook">webhook</a> from Drupal replaces every cached page with fresh content on the next request. See the <a href="./caching-model">caching model</a>.</li><li><strong>Search.</strong> An optional Livewire search page with tabs, filters, sorting and suggestions, answered from native JSON:API collections. An optional <a href="./index-extension">extension</a> adds Search API index support.</li><li><strong>Several backends.</strong> Content types can live on different Drupal sites (<a href="./vocabulary#source">Sources</a>), each with its own cache and webhook.</li><li><strong>Checks and test helpers.</strong> <code>drupal:contract</code> prints what your Drupal backend must provide, <code>drupal:validate</code> checks a live backend against it, and <code>FakesDrupal</code> builds JSON:API documents for your tests.</li></ul><h2 id="what-it-does-not-do" tabindex="-1">What it does not do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to &quot;What it does not do&quot;">​</a></h2><ul><li>It does not write to Drupal. The package only reads.</li><li>It does not ship a theme. The default views are bare HTML meant to be replaced.</li><li>It does not replace Drupal modules. The Drupal side stays your responsibility: the package prints a checklist (<a href="./artisan-commands"><code>drupal:contract</code></a>) and validates the result.</li><li>It does nothing until you declare a content type. With no content types the package registers no routes.</li></ul><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Version</th></tr></thead><tbody><tr><td>PHP</td><td>8.4 or later</td></tr><tr><td>Laravel</td><td>13</td></tr><tr><td>Livewire</td><td>4.3 or later</td></tr><tr><td>Drupal</td><td>11.3 or later, with core JSON:API and Decoupled Router</td></tr><tr><td>Indexed search (optional)</td><td>The <a href="./index-extension">Index extension</a>: Search API with a JSON:API Search API index</td></tr><tr><td>SEO metadata (optional)</td><td><code>ralphjsmit/laravel-seo</code></td></tr></tbody></table><p>Exact module versions are not specified. <a href="./backend-setup">Backend setup</a> lists what the Drupal side needs.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li>Follow the <a href="./quick-start">Quick start</a> to render one content type in about ten minutes.</li><li>Read the <a href="./vocabulary">Vocabulary</a> so the terms in the rest of the documentation are familiar.</li><li>Plan your real project with <a href="./installation">Installation</a> and <a href="./architecture">Architecture</a>.</li></ol>',13)])])}const f=t(n,[["render",i]]);export{p as __pageData,f as default};
